// Real Node Worker + V8 WebAssembly execution for the Rust guest ABI shape.
// IMPORTANT: bytecode is generated by a hand-authored test fixture, NOT from
// an .atto compiler. No compiler-backed parity or Chromium pass is claimed.
import test from 'node:test';
import assert from 'node:assert/strict';
import {Worker} from 'node:worker_threads';
import {createHash} from 'node:crypto';
import {BrowserTenantSupervisor} from '../src/browser-tenant-supervisor.mjs';
import {makeSyntheticAttoActorGuest} from './fixtures/synthetic-atto-integrated-actor.mjs';

const ADAPTER=new URL('./browser-atto-tenant-node-adapter.mjs',import.meta.url);
class NodeModuleWorker {
  #worker;
  constructor(_url,{type}={}){
    if(type!=='module')throw Error('real module Worker required');
    this.#worker=new Worker(ADAPTER,{type:'module'});
    this.#worker.on('message',data=>this.onmessage?.({data}));
    this.#worker.on('messageerror',error=>this.onmessageerror?.(error));
    this.#worker.on('error',error=>this.onerror?.(error));
    this.#worker.on('exit',code=>{
      if(code!==0)this.onerror?.(Error('Node Worker stopped with exit '+code));
    });
  }
  postMessage(message){this.#worker.postMessage(message);}
  terminate(){void this.#worker.terminate();}
}
const binary=makeSyntheticAttoActorGuest();
const digest=createHash('sha256').update(binary).digest('hex');
const manifests=[
  {name:'synthetic-handler-0',profile:'atto.browser.actor.integrated.v1',actorId:0,
    sha256:digest,bytes:binary},
  {name:'synthetic-handler-1',profile:'atto.browser.actor.integrated.v1',actorId:1,
    sha256:digest,bytes:binary},
];
const makeSupervisor=()=>new BrowserTenantSupervisor({
  workerUrl:'/browser-atto-tenant-worker.mjs',WorkerClass:NodeModuleWorker,
  manifest:manifests,deadlineMs:7000
});

test('real Node integrated Wasm: two actor instances/tenant and separate tenant Worker',async t=>{
  assert.equal(WebAssembly.validate(binary),true);
  const alpha=makeSupervisor(),beta=makeSupervisor();
  t.after(()=>{alpha.close();beta.close();});
  const a=await alpha.spawn(1,'synthetic-handler-0');
  const b=await alpha.spawn(2,'synthetic-handler-1');
  const c=await beta.spawn(1,'synthetic-handler-0');
  assert.deepEqual([
    await alpha.send(a,5n),await alpha.send(b,10n),
    await alpha.send(a,2n),await alpha.send(b,1n),
    await beta.send(c,3n)
  ],[5n,10n,7n,11n,3n]);
  assert.throws(()=>beta.send(a,1n),/unknown, stale/);
  await assert.rejects(alpha.send(a,-1n),/actor-local Wasm unreachable/);
  assert.equal(alpha.closed,false,'known unreachable is actor-local');
  assert.equal(await alpha.send(b,1n),12n,'healthy same-Worker actor preserved');
  assert.equal(await beta.send(c,1n),4n,'other Worker tenant preserved');
  const next=await alpha.spawn(1,'synthetic-handler-0');
  assert.throws(()=>alpha.send(a,1n),/unknown, stale/);
  assert.equal(await alpha.send(next,3n),3n,'reincarnated actor starts fresh');
  await alpha.stop(b);
  assert.throws(()=>alpha.send(b,1n),/unknown, stale/);
  assert.equal(await alpha.send(next,1n),4n);
});

test('real Node integrated Wasm: parent can reject wrong handler, profile and actor-shaped object',async t=>{
  const alpha=makeSupervisor();
  t.after(()=>alpha.close());
  await assert.rejects(alpha.spawn(3,'not-a-manifest-entry'),/not in trusted application manifest/);
  const ref=await alpha.spawn(1,'synthetic-handler-1');
  assert.throws(()=>alpha.send({id:1,incarnation:'0'.repeat(32)},1n),
    /unknown, stale/);
  assert.throws(()=>alpha.send(ref,()=>{}),/signed i64/);
  assert.equal(await alpha.send(ref,7n),7n);
});

test('real Node integrated Wasm: invalid artifact digest rejects spawn without harming tenant',async t=>{
  const worker=new NodeModuleWorker('/browser-atto-tenant-worker.mjs',{type:'module'});
  t.after(()=>worker.terminate());
  const pending=new Map(),incarnation='1'.repeat(32);
  let ticket=0;
  worker.onmessage=({data})=>{
    const slot=pending.get(data.ticket);
    if(!slot)return;
    clearTimeout(slot.timer);pending.delete(data.ticket);slot.resolve(data);
  };
  worker.onerror=error=>{
    for(const slot of pending.values()){clearTimeout(slot.timer);slot.reject(error);}
    pending.clear();
  };
  const ask=(kind,extra={})=>new Promise((resolve,reject)=>{
    const t=++ticket;
    const timer=setTimeout(()=>reject(Error('Node guest response timeout')),7000);
    pending.set(t,{resolve,reject,timer});
    worker.postMessage({ticket:t,id:1,incarnation,kind,...extra});
  });
  const invalid=await ask('spawn',{
    bytes:binary,approvedSha256:'0'.repeat(64),trusted:true,
    profile:'atto.browser.actor.integrated.v1',actorId:0
  });
  assert.equal(invalid.kind,'rejected');
  const permitted=await ask('spawn',{
    bytes:binary,approvedSha256:digest,trusted:true,
    profile:'atto.browser.actor.integrated.v1',actorId:1
  });
  assert.equal(permitted.kind,'ack');
  assert.equal((await ask('send',{value:5n})).result,5n);
  assert.equal((await ask('stop')).kind,'ack');
});
